{"PANDA": "import pandas as pd
from datetime import datetime
from dateutil.relativedelta import relativedelta

def convert_type(value):
    if isinstance(value, (int, float)):
        return value
    try:
        # Try to parse as integer
        cleaned = ''.join(c for c in str(value).strip() if c.isdigit() or c in '-+')
        if cleaned:
            return int(cleaned)
    except:
        pass
    try:
        # Try to parse as float
        cleaned = ''.join(c for c in str(value).strip() if c.isdigit() or c in '-+.eE')
        if cleaned:
            return float(cleaned)
    except:
        pass
    return value

# Find Robert Moran's term dates
robert_moran = df[df['Name'] == 'Robert Moran'].iloc[0]
start_year = convert_type(robert_moran['Term began'])
end_year = convert_type(robert_moran['Term ended'])

# Since terms are given as years, assume Jan 1 of start year to Jan 1 of end year
start_date = pd.to_datetime(f"{int(start_year)}-01-01")
end_date = pd.to_datetime(f"{int(end_year)}-01-01")

days_served = (end_date - start_date).days
days_served"}
